  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space);
}

.cards {
  display: grid;
  gap: var(--space);
  grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
}

@media (min-width: 48rem) {
